import assert from 'node:assert/strict';
import {startActionLab} from './action-lab.mjs';
const bytes=Buffer.alloc(0x600).toString('base64'),detailTile=Buffer.alloc(32).toString('base64');
const f={descriptor:1,props:0,origin_x:48,origin_y:68,parts:[],tiles:bytes,detail_variants:Array(20).fill(detailTile)},cycle={width:96,height:96,ticks:[2,16],frames:[f,f]};
const body={schema:'issd-pass-body-local/v2',rom_sha256:'test',team:2,kit:'home',skin:0,hair:0,palette:Array(16).fill(0),extra_palette:Array(16).fill(0),cycles:Object.fromEntries(Array.from({length:8},(_,i)=>[i,cycle]))};
const motion={schema:'issd-runtime-body-local/v1',cycles:{walking:Array.from({length:8},()=>({height:52}))}},preview={schema:'issd-editor-preview-local/v1',teams:Array.from({length:36},()=>({palettes:[Array(16).fill(0),Array(16).fill(0)]}))};
const detail={schema:'issd-team-detail-colors/v1',teams:Array.from({length:36},(_,team_id)=>({team_id,home:{selector:2,bgr555:31},away:{selector:2,bgr555:31}}))};
const palette=Array(16).fill('#000000'),catalog={teams:Array.from({length:36},(_,id)=>({id,name:'Equipe '+id,kit:{home:{sprite_palette:palette},away:{sprite_palette:palette}}}))};
const resources={'native-pass-body-local.json':body,'runtime-body-local.json':motion,'editor-preview-local.json':preview,'issd-team-detail-colors.json':detail,'issd-rom-catalog.json':catalog};
const createElement=()=>({value:'',textContent:'',disabled:false,children:[],listeners:{},addEventListener(type,cb){this.listeners[type]=cb;},replaceChildren(...x){this.children=x;},fire(type){this.listeners[type]?.();}});
const elements=Object.fromEntries(['kind','team','kit','direction','skin','hair','shirt','preview','play','tick','frame','status'].map(k=>['action-'+k,createElement()]));
Object.assign(elements['action-kind'],{value:'pass'});Object.assign(elements['action-kit'],{value:'home'});Object.assign(elements['action-direction'],{value:'2'});Object.assign(elements['action-skin'],{value:'0'});Object.assign(elements['action-shirt'],{value:'10'});
let draws=[];elements['action-preview'].getContext=()=>({clearRect(){},drawImage(...x){draws.push(x);}});
const doc={getElementById:id=>elements[id],createElement};let scheduled;
const env={fetch:async path=>{const data=resources[path.split('/').pop()];return {ok:!!data,json:async()=>data};},requestFrame:cb=>{scheduled=cb;},makeCanvas:(w,h)=>({width:w,height:h,getContext:()=>({createImageData:()=>({data:new Uint8ClampedArray(w*h*4)}),putImageData(){}})}),makeImage:()=>({complete:true,naturalWidth:576})};
await startActionLab(doc,env);
assert.equal(elements['action-team'].children.length,36);assert.equal(elements['action-hair'].children.length,14);
assert.equal(elements['action-play'].disabled,false);assert.ok(draws.length>0);assert.match(elements['action-status'].textContent,/Passe composto/);
assert.ok(Math.abs(draws.at(-1)[3]-96*96/52)<1e-9,'preview uses the locomotion reference scale');
elements['action-hair'].value='3';elements['action-hair'].fire('change');assert.match(elements['action-status'].textContent,/cabelo.*não foi validada/);
elements['action-tick'].value='7';elements['action-tick'].fire('input');assert.equal(elements['action-frame'].textContent,'8 / 18');assert.equal(elements['action-play'].textContent,'Reproduzir');
elements['action-play'].fire('click');assert.equal(elements['action-play'].textContent,'Pausar');scheduled(100);scheduled(150);assert.equal(elements['action-frame'].textContent,'11 / 18');
elements['action-kind'].value='shot';elements['action-kind'].fire('change');assert.match(elements['action-status'].textContent,/Chute provisório/);assert.equal(draws.at(-1).length,9);
console.log('OK: laboratório permite selecionar e inspecionar passe e chute');
